cases = [
    {"q": "sets dedupe", "gold": "d2"},
    {"q": "cosine similarity", "gold": "d3"},
]
preds = {"sets dedupe": ["d2", "d1"], "cosine similarity": ["d1"]}

def recall_at_k(cases, preds, k):
    hits = sum(1 for c in cases if c["gold"] in preds.get(c["q"], [])[:k])
    return round(hits / len(cases), 3)

print("recall@1", recall_at_k(cases, preds, 1))
print("recall@2", recall_at_k(cases, preds, 2))
print("frozen eval set size", len(cases))
